import{I as e,c as a,d as r,O as d}from"./chunks/framework.N7KwZWfa-ghp20261122.js";const g=JSON.parse('{"title":"暗夜之影／午夜魅影活動攻略","description":"少女迴戰 2026 年 11 月第 29 期彈珠活動。檢視日服暗夜之影和繁中服午夜魅影的開放時段、現在·幽靈再現碎片、三件新寶物和兌換條件。","frontmatter":{"title":"暗夜之影／午夜魅影活動攻略","description":"少女迴戰 2026 年 11 月第 29 期彈珠活動。檢視日服暗夜之影和繁中服午夜魅影的開放時段、現在·幽靈再現碎片、三件新寶物和兌換條件。","breadcrumbLabel":"暗夜之影／午夜魅影","breadcrumbs":[["/events/","限時活動"]],"socialImage":"/images/ghost-return/event-banner.webp","lastmod":"2026-11-20"},"headers":[],"relativePath":"events/dark-shadow/index.md","filePath":"events/dark-shadow/index.md"}'),h={name:"events/dark-shadow/index.md"};function n(s,t,l,i,o,b){return a(),r("div",null,[...t[0]||(t[0]=[d('<article class="page-shell knowledge-page reference-guide"><h1 id="暗夜之影-午夜魅影" tabindex="-1">暗夜之影／午夜魅影 <a class="header-anchor" href="#暗夜之影-午夜魅影" aria-label="Permalink to &quot;暗夜之影／午夜魅影&quot;">​</a></h1><p>「暗夜之影」是日服《少女廻戦》2026 年 11 月的第 29 期彈珠活動，原名「闇夜の影」，繁中服名為「午夜魅影」。主會場包含活躍任務、劇情、秘寶、特賣和兌換。彈珠獎勵可開出「現在·幽靈再現」的碎片。</p><img src="/images/ghost-return/event-banner.webp" alt="暗夜之影與午夜魅影的原版彈珠活動橫幅" width="928" height="300"><h2 id="兩服時間" tabindex="-1">兩服時間 <a class="header-anchor" href="#兩服時間" aria-label="Permalink to &quot;兩服時間&quot;">​</a></h2><table tabindex="0"><thead><tr><th>區服</th><th>彈珠排行</th><th>日常任務鋼珠券</th></tr></thead><tbody><tr><td>日服 · 日本時間</td><td>2026-11-19 11:10 至 2026-11-25 23:59:59</td><td>2026-11-20 00:00 至 2026-11-25 23:59:59</td></tr><tr><td>繁中服 · 臺港澳時間</td><td>2026-11-20 10:40 至 2026-11-26 23:59:59</td><td>2026-11-21 00:00 至 2026-11-26 23:59:59</td></tr></tbody></table><p>表內時段來自各服客戶端的彈珠排行與日常產出配置。 <a href="/zh-hant/events/#current">本期活動</a></p><h2 id="彈珠怎麼玩" tabindex="-1">彈珠怎麼玩 <a class="header-anchor" href="#彈珠怎麼玩" aria-label="Permalink to &quot;彈珠怎麼玩&quot;">​</a></h2><p>每次購買普通鋼珠消耗 5 張鋼珠券，購買雙倍對應玩法需 5 張雙倍鋼珠券。發射後領取命中袋子的獎勵。連續 7 次搖獎未中獎時，補償 5 張雙倍鋼珠券。購買鋼珠用的券與兌換用的活動獎券是兩種道具。</p><h2 id="hero-shards" tabindex="-1">現在·幽靈再現碎片 <a class="header-anchor" href="#hero-shards" aria-label="Permalink to &quot;現在·幽靈再現碎片 {#hero-shards}&quot;">​</a></h2><ul><li>彈珠命中對應袋子可獲得武將限定禮盒，開啟後可選擇 2 枚碎片。</li><li>秘寶第二進階檔的第 2 檔給 20 個武將自選禮盒，每個可選 2 枚該武將碎片。</li><li>合成「現在·幽靈再現」需要 180 枚。 <a href="/zh-hant/heroes/603680">武將詳情</a> · <a href="/zh-hant/art-library/?asset=hero-603680">檢視原版立繪</a></li></ul><h2 id="rewards" tabindex="-1">活躍與累計獎勵 <a class="header-anchor" href="#rewards" aria-label="Permalink to &quot;活躍與累計獎勵 {#rewards}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>活躍度</th><th style="text-align:right;">鋼珠券</th><th style="text-align:right;">攝像機碎片</th><th>其他獎勵</th></tr></thead><tbody><tr><td>20</td><td style="text-align:right;">2</td><td style="text-align:right;">30</td><td>—</td></tr><tr><td>60</td><td style="text-align:right;">2</td><td style="text-align:right;">20</td><td>—</td></tr><tr><td>100</td><td style="text-align:right;">3</td><td style="text-align:right;">20</td><td>—</td></tr><tr><td>150</td><td style="text-align:right;">4</td><td style="text-align:right;">20</td><td>—</td></tr><tr><td>200</td><td style="text-align:right;">—</td><td style="text-align:right;">—</td><td>雙倍鋼珠券 ×5、英魂自選禮包 ×1</td></tr></tbody></table><p>彈珠累計達到 90、210、300 時，每檔還可再獲得偷拍攝像機碎片 ×30。 <a href="/zh-hant/bonds/treasures/700934/">偷拍攝像機詳情</a></p><h2 id="exchange" tabindex="-1">新寶物與兌換 <a class="header-anchor" href="#exchange" aria-label="Permalink to &quot;新寶物與兌換 {#exchange}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>寶物</th><th>獲取方式</th><th>10 星全體武將加成</th></tr></thead><tbody><tr><td><a href="/zh-hant/bonds/treasures/700934/">偷拍攝像機</a></td><td>活躍與累計獎勵可拿碎片。兌換第 3 階段用 40 張活動獎券換碎片 ×60，限 6 次</td><td>生命值 +9.00%、力量 +3,100</td></tr><tr><td><a href="/zh-hant/bonds/treasures/703680/">水果手機</a></td><td>立繪手機可領本體。兌換第 2 階段用 40 張活動獎券換碎片 ×60，限 7 次</td><td>生命值 +9.00%</td></tr><tr><td><a href="/zh-hant/bonds/treasures/700935/">高定高跟鞋</a></td><td>特賣紀念禮盒Ⅱ中自選本體</td><td>攻擊力 +3.00%、會心一擊傷害 +3.00%</td></tr></tbody></table><p>兌換第 2、3 階段分別需要上一階段的兌換進度達到 1 次。繁中服兌換貨幣原名「午夜魅影獎券」。</p><h3 id="heels" tabindex="-1">高定高跟鞋禮包 <a class="header-anchor" href="#heels" aria-label="Permalink to &quot;高定高跟鞋禮包 {#heels}&quot;">​</a></h3><p>日服特賣的「闇夜の影特売品記念」與繁中服的「午夜魅影大暴走紀念」均包含對應紀念禮盒Ⅱ。開啟禮盒，從獎勵選項中選擇高定高跟鞋本體 ×1。 <a href="/zh-hant/bonds/treasures/700935/">高定高跟鞋詳情</a></p><h2 id="資料來源" tabindex="-1">資料來源 <a class="header-anchor" href="#資料來源" aria-label="Permalink to &quot;資料來源&quot;">​</a></h2><p>活動入口、獎勵及排期按 2026 年 11 月官方客戶端記錄核對。 <a href="https://shupdate.menaapp.net/updatePackage/android/0.821/0_821_6/versions.csv" target="_blank" rel="noreferrer">日服 0.821.6 客戶端清單</a> · <a href="https://shtwnupdate.menaapp.net/updatePackage/android/0.840/0_840_61/versions.csv" target="_blank" rel="noreferrer">繁中服 0.840.61 客戶端清單</a></p></article>',1)])])}const p=e(h,[["render",n]]);export{g as __pageData,p as default};
